class BankAccount:
    def __init__(self, balance=0):
        self.balance = balance
    def withdraw(self, amount):
        if amount > self.balance:
            return False
        self.balance -= amount
        return True

acc = BankAccount(100)
print(acc.withdraw(30), acc.withdraw(80), acc.balance)

class Machine:
    def __init__(self):
        self.stock = {}
    def refill(self, product, qty):
        self.stock[product] = min(10, self.stock.get(product, 0) + qty)
    def buy(self, product):
        if self.stock.get(product, 0) > 0:
            self.stock[product] -= 1
            return product
        return None

m = Machine()
m.refill('soda', 8)
m.refill('soda', 5)
m.buy('soda')
print(m.stock['soda'], m.buy('chips'))

import math

class Point2D:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def distance(self, other=None):
        if other is None:
            other = Point2D(0, 0)
        return math.hypot(self.x - other.x, self.y - other.y)

a = Point2D(3, 4)
b = Point2D(6, 8)
print(a.distance(), Point2D.distance(b, a))

